// ALG-DESCENT-16: exact packed native Horn certification; C++17.
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <memory_resource>
#include <random>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>
#include <sys/resource.h>
using U8=uint8_t; using U16=uint16_t; using U32=uint32_t; using U64=uint64_t;
using Clock=std::chrono::steady_clock;
constexpr int N=18,R=45,P=15,INF=255;
constexpr std::array<int,6> budgets{0,4,16,32,64,128};
void require(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
int bit(U64 x){return __builtin_ctzll(x);}
struct Rule{U32 prem=0;U8 head=0,cost=0;};
struct Graph{U32 seed=0,initial=7,relevant=0,goalbit=0;int n=0,nr=0;std::array<Rule,R> rules{};std::array<int,N+1> begin{};};
std::vector<Graph> load(const char* p){std::ifstream f(p);int count=0;require(bool(f>>count)&&count>0&&count<=1000,"graph count");std::vector<Graph> out;for(int j=0;j<count;j++){Graph g;require(bool(f>>g.seed>>g.n>>g.nr)&&g.n>=4&&g.n<=N&&g.nr>0&&g.nr<=R,"graph size");g.goalbit=1u<<(g.n-1);int pos=0;for(int i=0;i<g.nr;i++){int h,c;U32 m;require(bool(f>>h>>m>>c)&&h>=3&&h<g.n&&m<(1u<<h)&&m&&c>=1&&c<=7,"rule");while(pos<=h)g.begin[pos++]=i;require(h==pos-1,"rule order");g.rules[i]={m,U8(h),U8(c)};}while(pos<=g.n)g.begin[pos++]=g.nr;for(int h=3;h<g.n;h++)require(g.begin[h]<g.begin[h+1],"missing derivation");g.relevant=g.goalbit;for(int h=g.n-1;h>=3;h--)if(g.relevant&(1u<<h))for(int i=g.begin[h];i<g.begin[h+1];i++)g.relevant|=g.rules[i].prem;out.push_back(g);}std::string extra;require(!(f>>extra),"trailing input");return out;}
struct Track final:std::pmr::memory_resource{size_t live=0,peak=0,total=0,calls=0;void* do_allocate(size_t n,size_t a)override{void* p=std::pmr::new_delete_resource()->allocate(n,a);live+=n;peak=std::max(peak,live);total+=n;calls++;return p;}void do_deallocate(void* p,size_t n,size_t a)override{require(n<=live,"allocation accounting");live-=n;std::pmr::new_delete_resource()->deallocate(p,n,a);}bool do_is_equal(const std::pmr::memory_resource& x)const noexcept override{return this==&x;}};
struct Path{std::array<U8,P> ids{};U8 len=0;void add(int i){require(len<P&&i>=0&&i<R,"path bound");ids[len++]=U8(i);}bool operator==(const Path& p)const{return len==p.len&&std::equal(ids.begin(),ids.begin()+len,p.ids.begin());}};
Path cat(Path a,const Path& b){for(int i=0;i<b.len;i++)a.add(b.ids[i]);return a;}
struct Residual{std::array<U8,R> a{};std::array<U8,N> d{};U8 charge=0;};
struct Node{U32 s=0,serial=0;U16 ri=0;U8 best=INF,b=0,ffcost=INF;bool coarse=false,done=false,open=false;Path path{},ff{};};
struct Item{int f,b,g;U32 serial,id;bool operator<(const Item& x)const{return std::tie(f,b,g,serial)>std::tie(x.f,x.b,x.g,x.serial);}};
enum Counter{EXP,PROBES,COARSE,FULL,CUTS,REFINE,DSCAN,BSCAN,MSCAN,FFC,VER,VERST,DUP,REOPEN,PRUNE,POPEN,PBEST,PQUEUE,PCACHE,UNION,HITS,MISSES,ZONES,ZIDS,NC};
constexpr const char* names[NC]={"expansions","probes","coarse_calls","full_bounds","cut_rounds","refinements","distance_scans","boundary_scans","minimum_scans","ff_calls","verify_calls","verify_steps","duplicates","reopened","pruned","peak_open","peak_best","peak_queue","peak_bound_cache","unions","zone_hits","zone_misses","zone_entries","zone_rule_ids"};
using Counts=std::array<U64,NC>;
struct Snap{int cap=0,L=0,U=0,open=0;Path proof{};Counts c{};bool operator==(const Snap& x)const{return cap==x.cap&&L==x.L&&U==x.U&&open==x.open&&proof==x.proof&&c==x.c;}};
struct Event{char kind;U32 s;int g=0,old=0,next=0;U32 zone=0;int delta=0;U64 mask=0;Path path{};};
struct Result{std::array<Snap,6> snaps{};U64 hash=1469598103934665603ULL;size_t peak=0,live=0,total=0,allocs=0;bool same(const Result& x)const{return snaps==x.snaps&&hash==x.hash&&peak==x.peak&&live==x.live&&total==x.total&&allocs==x.allocs;}};
struct Engine{const Graph& g;int arm;Track& tr;std::pmr::vector<Node> nodes;std::pmr::vector<Residual> residuals;std::pmr::unordered_map<U32,U32> ids;std::pmr::vector<Item> heap;std::pmr::unordered_map<U32,U64> zones;std::array<U64,N> heads{},prem{};std::array<U32,N> desc{};Counts c{};U32 serial=0;int opens=0,U=INF;Path incumbent{};Result res{};std::vector<Event>* log;
Engine(const Graph& gg,int a,Track& t,std::vector<Event>* l):g(gg),arm(a),tr(t),nodes(&t),residuals(&t),ids(&t),heap(&t),zones(&t),log(l){if(arm==2){for(int h=0;h<g.n;h++)desc[h]=1u<<h;for(int i=0;i<g.nr;i++){auto r=g.rules[i];heads[r.head]|=1ULL<<i;for(U32 p=r.prem;p;p&=p-1)prem[bit(p)]|=1ULL<<i;}for(int h=g.n-1;h>=0;h--)for(U64 p=prem[h];p;p&=p-1)desc[h]|=desc[g.rules[bit(p)].head];}}
void event(Event e){auto mix=[&](U64 x){res.hash=(res.hash^x)*1099511628211ULL;};mix(e.kind);mix(e.s);mix(e.g);mix(e.old);mix(e.next);mix(e.zone);mix(e.delta);mix(e.mask);mix(e.path.len);for(int j=0;j<e.path.len;j++)mix(e.path.ids[j]);if(log)log->push_back(e);}
U32 get(U32 s){auto it=ids.find(s);if(it!=ids.end())return it->second;U32 id=nodes.size();require(id<65535,"node count");nodes.push_back(Node{});nodes.back().s=s;ids.emplace(s,id);c[PBEST]=std::max(c[PBEST],U64(nodes.size()));return id;}
void remove(U32 id){if(nodes[id].open){nodes[id].open=false;--opens;}}
void distance(U32 s,Residual& q,U32 dirty){for(int h=3;h<g.n;h++)if(!(s&(1u<<h))&&(dirty&(1u<<h))){int m=INF;for(int i=g.begin[h];i<g.begin[h+1];i++){int v=0;for(U32 p=g.rules[i].prem;p;p&=p-1)v=std::max(v,int(q.d[bit(p)]));m=std::min(m,v+q.a[i]);c[DSCAN]++;}require(m<INF,"distance overflow");q.d[h]=U8(m);}}
void coarse(U32 id){auto& n=nodes[id];if(n.coarse)return;Residual q;for(int i=0;i<g.nr;i++)q.a[i]=g.rules[i].cost;distance(n.s,q,(1u<<g.n)-1);n.b=q.d[g.n-1];n.coarse=true;n.done=n.b==0;c[COARSE]++;c[PCACHE]=c[COARSE];if(arm&&n.done)c[FULL]++;if(arm){require(residuals.size()<65535,"residual index");n.ri=U16(residuals.size());residuals.push_back(q);}event({'B',n.s,0,0,n.b});}
U64 boundary(U32 z){if(arm==1){U64 m=0;for(int i=0;i<g.nr;i++){auto r=g.rules[i];if((z&(1u<<r.head))&&!(z&r.prem))m|=1ULL<<i;}c[BSCAN]+=g.nr;return m;}auto it=zones.find(z);if(it!=zones.end()){c[HITS]++;return it->second;}c[MISSES]++;U64 h=0,p=0;for(U32 x=z;x;x&=x-1){h|=heads[bit(x)];p|=prem[bit(x)];c[UNION]+=2;}U64 m=h&~p;zones.emplace(z,m);c[ZONES]=zones.size();c[ZIDS]+=__builtin_popcountll(m);return m;}
void refine(U32 id){auto& n=nodes[id];auto& q=residuals[n.ri];int h=q.d[g.n-1],old=n.b;require(!n.done&&h>0,"bad refinement");U32 z=0;for(int j=3;j<g.n;j++)if(q.d[j]>=h&&(g.relevant&(1u<<j)))z|=1u<<j;require((z&g.goalbit)&&!(z&n.s),"bad zone");U64 m=boundary(z);require(m,"empty boundary");int delta=INF;for(U64 x=m;x;x&=x-1){delta=std::min(delta,int(q.a[bit(x)]));c[MSCAN]++;}require(delta>0&&delta<INF,"bad delta");U32 dirty=0;for(U64 x=m;x;x&=x-1){int i=bit(x);q.a[i]-=delta;if(arm==2)dirty|=desc[g.rules[i].head];}require(int(q.charge)+delta<INF,"charge overflow");q.charge+=delta;distance(n.s,q,arm==2?dirty:(1u<<g.n)-1);n.b=std::max(int(n.b),int(q.charge)+q.d[g.n-1]);n.done=q.d[g.n-1]==0;c[CUTS]++;c[REFINE]++;c[FULL]+=n.done;event({'C',n.s,n.best,old,n.b,z,delta,m});}
void ff(U32 id){auto& n=nodes[id];if(n.ffcost!=INF)return;c[FFC]++;std::array<int,N> v{},chosen{};for(int h=3;h<g.n;h++)if(!(n.s&(1u<<h))){int cost=100000,which=-1;for(int i=g.begin[h];i<g.begin[h+1];i++){int a=g.rules[i].cost;for(U32 p=g.rules[i].prem;p;p&=p-1)a+=v[bit(p)];if(a<cost){cost=a;which=i;}}v[h]=cost;chosen[h]=which;}U32 need=g.goalbit&~n.s;for(int h=g.n-1;h>=3;h--)if(need&(1u<<h))need|=g.rules[chosen[h]].prem&~n.s;int cost=0;for(int h=3;h<g.n;h++)if(need&(1u<<h)){n.ff.add(chosen[h]);cost+=g.rules[chosen[h]].cost;}require(cost<INF,"FF proof cost");n.ffcost=U8(cost);}
void verify(const Path& p,int cost){c[VER]++;c[VERST]+=p.len;U32 s=g.initial;int paid=0;for(int j=0;j<p.len;j++){int i=p.ids[j];require(i<g.nr,"rule ID");auto r=g.rules[i];require(!(s&(1u<<r.head))&&(s&r.prem)==r.prem,"invalid proof");s|=1u<<r.head;paid+=r.cost;}require((s&g.goalbit)&&paid==cost,"invalid incumbent");}
void push(U32 id){auto& n=nodes[id];require(!n.open,"duplicate open");n.open=true;opens++;heap.push_back({n.best+n.b,n.b,n.best,n.serial,id});std::push_heap(heap.begin(),heap.end());c[POPEN]=std::max(c[POPEN],U64(opens));c[PQUEUE]=std::max(c[PQUEUE],U64(heap.size()));}
void admit(U32 id){coarse(id);auto& n=nodes[id];if(n.best+n.b>=U){c[PRUNE]++;return;}n.serial=++serial;push(id);}
void improve(int cost,Path p){if(cost>=U)return;verify(p,cost);U=cost;incumbent=p;for(U32 i=0;i<nodes.size();i++)if(nodes[i].open&&nodes[i].best+nodes[i].b>=U){remove(i);c[PRUNE]++;}}
void pop(){std::pop_heap(heap.begin(),heap.end());heap.pop_back();}
Result execute(){U32 root=get(g.initial);nodes[root].best=0;ff(root);U=nodes[root].ffcost;incumbent=nodes[root].ff;verify(incumbent,U);admit(root);for(int k=0;k<6;k++){int cap=budgets[k];while(c[EXP]<U64(cap)&&opens){while(!heap.empty()){auto t=heap.front();auto& n=nodes[t.id];if(n.open&&n.serial==t.serial&&n.b==t.b)break;pop();}require(!heap.empty(),"lost frontier");U32 id=heap.front().id;Node n=nodes[id];require(n.best+n.b<U,"stale bound");bool need=arm&&!n.done;if(need&&c[REFINE]>=4096)break;pop();remove(id);if(need){refine(id);if(nodes[id].best+nodes[id].b>=U)c[PRUNE]++;else push(id);continue;}event({'E',n.s,n.best,0,0,0,0,0,n.path});c[EXP]++;ff(id);improve(n.best+nodes[id].ffcost,cat(n.path,nodes[id].ff));c[PROBES]+=g.nr;for(int h=3;h<g.n;h++)if(!(n.s&(1u<<h))){int best=INF,rule=-1;for(int i=g.begin[h];i<g.begin[h+1];i++)if((n.s&g.rules[i].prem)==g.rules[i].prem&&g.rules[i].cost<best){best=g.rules[i].cost;rule=i;}if(rule<0)continue;U32 t=n.s|(1u<<h),j=get(t);int gc=n.best+best;auto& child=nodes[j];if(gc>=child.best){c[DUP]++;continue;}if(child.best<INF&&!child.open)c[REOPEN]++;remove(j);child.best=U8(gc);child.path=n.path;child.path.add(rule);if(t&g.goalbit)improve(gc,child.path);else admit(j);}}
int L=U;for(auto& n:nodes)if(n.open)L=std::min(L,int(n.best)+n.b);res.snaps[k]={cap,L,U,opens,incumbent,c};}res.peak=tr.peak;res.live=tr.live;res.total=tr.total;res.allocs=tr.calls;return res;}
};
Result run(const Graph& g,int arm,std::vector<Event>* log=nullptr){Track t;Result r;{Engine e(g,arm,t,log);r=e.execute();}require(t.live==0,"leaked search allocation");return r;}
void pathout(const Path& p){std::cout<<' '<<int(p.len);for(int i=0;i<p.len;i++)std::cout<<' '<<int(p.ids[i]);}
int main(int argc,char** argv){try{require(argc>=2,"usage: native bank [reps]");int reps=argc>2?std::stoi(argv[2]):61;require(reps>0&&reps<=1001,"repetitions");auto graphs=load(argv[1]);std::cout<<"LAYOUT "<<sizeof(Node)<<' '<<sizeof(Residual)<<' '<<sizeof(Item)<<' '<<sizeof(Engine)<<' '<<sizeof(Graph)<<' '<<sizeof(Track)<<' '<<sizeof(Result)<<'\n';std::cout<<"COUNTERS";for(auto s:names)std::cout<<' '<<s;std::cout<<'\n';for(auto& g:graphs){std::array<Result,3> first{};std::array<std::vector<U64>,3> times;std::array<int,3> order{0,1,2};std::mt19937 rng(g.seed);for(int rep=0;rep<reps;rep++){std::shuffle(order.begin(),order.end(),rng);for(int arm:order){auto t=Clock::now();auto r=run(g,arm);U64 ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-t).count();if(rep==0)first[arm]=r;else require(r.same(first[arm]),"non-deterministic timed run");times[arm].push_back(ns);}}for(int arm=0;arm<3;arm++){std::vector<Event> events;auto r=run(g,arm,&events);require(r.same(first[arm]),"trace mismatch");std::cout<<"R "<<g.seed<<' '<<arm<<'\n';for(auto& e:events){std::cout<<e.kind<<' '<<e.s;if(e.kind=='B')std::cout<<' '<<e.next;else if(e.kind=='C')std::cout<<' '<<e.g<<' '<<e.old<<' '<<e.next<<' '<<e.zone<<' '<<e.delta<<' '<<e.mask;else{std::cout<<' '<<e.g;pathout(e.path);}std::cout<<'\n';}for(auto& s:r.snaps){std::cout<<"S "<<s.cap<<' '<<s.L<<' '<<s.U<<' '<<s.open;for(U64 v:s.c)std::cout<<' '<<v;pathout(s.proof);std::cout<<'\n';}auto t=times[arm];std::sort(t.begin(),t.end());std::cout<<"M "<<t[t.size()/2]<<' '<<r.peak<<' '<<r.live<<' '<<r.total<<' '<<r.allocs<<' '<<r.hash<<' '<<reps<<'\n';}}rusage ru{};getrusage(RUSAGE_SELF,&ru);std::cout<<"RSS "<<ru.ru_maxrss<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
